#include <bits/stdc++.h>
#define fi first
#define se second
#define pb push_back
#define all(x) x.begin(), x.end()
#define rall(x) x.rbegin(), x.rend()
#define loop(i, a, b) for(int i = a; i < b; i++)
#define loopBack(i, a, b) for(int i = a; i >= b; i--)
#define INF INT_MAX
#define LINF LLONG_MAX
#define DINF DBL_MAX
#define MAX 150
#define MOD 1000
using namespace std;
typedef long long int ll;
typedef pair<int, int> ii;

struct FlowEdge {
    int v, u;
    ll cap, flow = 0;
    FlowEdge(int v, int u, ll cap) : v(v), u(u), cap(cap) {}
};

struct Dinic {
    const ll flow_inf = 1e18;
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    int n, m = 0;
    int s, t;
    vector<int> level, ptr;
    queue<int> q;

    Dinic(int n, int s, int t) : n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void add_edge(int v, int u, ll cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(m);
        adj[u].push_back(m + 1);
        m += 2;
    }

    bool bfs() {
        fill(all(level), -1);
        level[s] = 0;
        q = queue<int>();
        q.push(s);
        while(!q.empty()) {
            int v = q.front(); q.pop();
            for(auto viz : adj[v]) {
                if(edges[viz].cap - edges[viz].flow < 1) continue;
                if(level[edges[viz].u] != -1) continue;
                level[edges[viz].u] = level[v] + 1;
                q.push(edges[viz].u);
            }
        }
        return level[t] != -1;
    }

    ll sendFlow(int v, ll pushed) {
        if(pushed == 0) return 0;
        if(v == t) return pushed;
        for(int &i = ptr[v]; i < (int)adj[v].size(); i++) {
            int viz = adj[v][i];
            int u = edges[viz].u;
            if(level[v] + 1 != level[u] || edges[viz].cap - edges[viz].flow < 1) continue;
            ll tr = sendFlow(u, min(pushed, edges[viz].cap - edges[viz].flow));
            if(tr == 0) continue;
            edges[viz].flow += tr;
            edges[viz ^ 1].flow -= tr;
            return tr;
        }
        return 0;
    }

    ll maxFlow() {
        ll total = 0;
        while(bfs()) {
            fill(all(ptr), 0);
            while(ll pushed = sendFlow(s, flow_inf))
                total += pushed;
        }
        return total;
    }
};

int pos[MAX][MAX], matTempo[MAX][MAX], matAlc[MAX][MAX];

vector<ii> getNeighbors(int i, int j, vector<string> mat, int n) {
    vector<ii> neighbors;
    if(i + 1 < n) neighbors.pb({i+1, j});
    if(i - 1 >= 0) neighbors.pb({i-1, j});
    if(j + 1 < n) neighbors.pb({i, j+1});
    if(j - 1 >= 0) neighbors.pb({i, j-1});
    return neighbors;
}

void fillMatTempo(int i, int j, vector<string> sc, int n, int currT) {
    if(i >= n || i < 0 || j >= n || j < 0 || (!isdigit(sc[i][j]) && sc[i][j] != 'Z') || (matTempo[i][j] != -1 && matTempo[i][j] <= currT))
        return;
    if(matTempo[i][j] == -1)
        matTempo[i][j] = currT;
    else
        matTempo[i][j] = min(currT, matTempo[i][j]);
    fillMatTempo(i+1, j, sc, n, currT+1);
    fillMatTempo(i-1, j, sc, n, currT+1);
    fillMatTempo(i, j+1, sc, n, currT+1);
    fillMatTempo(i, j-1, sc, n, currT+1);
}

void fillMatAlc(int i, int j, vector<string> sc, int n, int currT) {
    if(i >= n || i < 0 || j >= n || j < 0 || (matAlc[i][j] != -1 && matAlc[i][j] <= currT) || !isdigit(sc[i][j]))
        return;
    if(matAlc[i][j] == -1)
        matAlc[i][j] = currT;
    else
        matAlc[i][j] = min(currT, matAlc[i][j]);
    fillMatAlc(i+1, j, sc, n, currT+1);
    fillMatAlc(i-1, j, sc, n, currT+1);
    fillMatAlc(i, j+1, sc, n, currT+1);
    fillMatAlc(i, j-1, sc, n, currT+1);
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(nullptr);
    int n, t, n2, nMax, iZ, jZ;
    string aux;

    cin >> n >> t;
    n2 = n * n;
    nMax = n2 * 2;
    Dinic graph(nMax + 2, 0, nMax + 1);
    vector<string> sc(n), caps(n);

    int cnt = 1;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            pos[i][j] = cnt++;
        }
    }

    for(int i = 0; i < n; i++) {
        cin >> sc[i];
        for(int j = 0; j < n; j++) {
            if(sc[i][j] == 'Z') {
                iZ = i; jZ = j;
            }
        }
    }
    for(int i = 0; i < n; i++) cin >> caps[i];

    memset(matTempo, -1, sizeof(matTempo));
    fillMatTempo(iZ, jZ, sc, n, 0);
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(matTempo[i][j] == -1 && isdigit(sc[i][j]))
                matTempo[i][j] = t;
        }
    }

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            memset(matAlc, -1, sizeof(matAlc));
            if(isdigit(sc[i][j])) {
                int limit = sc[i][j] - '0';
                graph.add_edge(0, pos[i][j], limit);
                fillMatAlc(i, j, sc, n, 0);
                for(int k = 0; k < n; k++) {
                    for(int l = 0; l < n; l++) {
                        if(matAlc[k][l] != -1 && matTempo[k][l] != -1 && matAlc[k][l] <= matTempo[k][l] && matAlc[k][l] <= t) {
                            bool crt = true;
                            if(matAlc[k][l] == matTempo[k][l]) {
                                crt = false;
                                if(k+1 < n && matAlc[k+1][l] != -1 && matAlc[k+1][l] < matTempo[k+1][l]) crt = true;
                                if(k-1 >= 0 && matAlc[k-1][l] != -1 && matAlc[k-1][l] < matTempo[k-1][l]) crt = true;
                                if(l+1 < n && matAlc[k][l+1] != -1 && matAlc[k][l+1] < matTempo[k][l+1]) crt = true;
                                if(l-1 >= 0 && matAlc[k][l-1] != -1 && matAlc[k][l-1] < matTempo[k][l-1]) crt = true;
                            }
                            if(crt) {
                                graph.add_edge(pos[i][j], n2 + pos[k][l], limit);
                            }
                        }
                    }
                }
            }
        }
    }

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(isdigit(caps[i][j])) {
                graph.add_edge(n2 + pos[i][j], nMax + 1, caps[i][j] - '0');
            }
        }
    }

    ll answer = graph.maxFlow();
    cout << answer << '\n';
}
